using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorInspectorOperations
{
    private readonly ActorProjectFilePickerOperations _picker=new();
    private static string[] Extensions(Resource property)=>property.Get("options").AsGodotDictionary().GetValueOrDefault("extensions",Array.Empty<string>()).AsStringArray();
    public bool is_shader_property(Resource property)=>Extensions(property).Contains("gdshader");public bool is_mesh_property(Resource property){var extensions=Extensions(property);return extensions.Contains("glb")||extensions.Contains("mesh");}
    public bool file_path_allowed(Control owner,string path,Resource property)
    {
        var options=property.Get("options").AsGodotDictionary();if(!_picker.is_allowed_path(_picker.root_directory(),path,Extensions(property)))return false;var types=options.GetValueOrDefault("native_resource_types",Array.Empty<string>()).AsStringArray();string extension=path.GetExtension().ToLowerInvariant();if(options.GetValueOrDefault("shader_texture",false).AsBool()&&extension is "tres" or "res"){var resource=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);return resource is Texture2D||ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")&&_definitions.object_type_matches(Ui<RefCounted>(owner,"registry"),resource!.Get("type_id").AsStringName(),"image");}if(types.Length==0||extension is not ("tres" or "res" or "mesh"))return true;string root=ProjectSettings.GlobalizePath("res://").Replace('\\','/').TrimEnd('/'),normalized=path.Replace('\\','/');string load=normalized.StartsWith(root+"/",StringComparison.Ordinal)?"res://"+normalized[(root.Length+1)..]:path;var value=ResourceLoader.Load(load,"",ResourceLoader.CacheMode.Ignore);return types.Contains("Mesh")&&value is Mesh||types.Contains("PackedScene")&&value is PackedScene||types.Contains("KiwiTransformationImage2D")&&ActorDataOperations.ScriptIs(value,"res://Workspaces/TransformationWorkspace/transformation_document.gd");
    }
    public bool property_accepts_image(Resource property)=>property.Get("options").AsGodotDictionary().GetValueOrDefault("accepted_object_types",new GArray{property.Get("object_type").AsString()}).AsStringArray().Contains("image");
    public bool is_raw_image_path(string path)=>ImageExtensions.Contains(path.GetExtension().ToLowerInvariant());
    public Resource object_picker_property(Resource property){if(!property_accepts_image(property))return property;var copy=property.Duplicate(true);var options=property.Get("options").AsGodotDictionary().Duplicate(true);var extensions=options.GetValueOrDefault("extensions",Array.Empty<string>()).AsStringArray().ToList();foreach(string extension in ImageExtensions)if(!extensions.Contains(extension))extensions.Add(extension);options["extensions"]=extensions.ToArray();options["raw_extensions"]=(string[])ImageExtensions.Clone();copy.Set("options",options);return copy;}
    public bool object_resource_path_allowed(Control owner,string path,Resource property){if(!file_path_allowed(owner,path,object_picker_property(property)))return false;if(is_raw_image_path(path)&&property_accepts_image(property))return true;var loaded=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);return ActorDataOperations.ScriptIs(loaded,"res://scripts/actors/core/actor_object_data.gd")&&_properties.accepts(property,_data.from_asset(path,loaded!.Get("type_id").AsStringName()));}
    public string file_resource_type_name(Resource property){var extensions=Extensions(property);return extensions.Contains("mp4")?"Video":extensions.Contains("mp3")?"Audio":is_shader_property(property)?"Shader":is_mesh_property(property)?"Mesh / 3D Model":"Image";}
    public string file_resource_display_name(Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource resource){if(ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_reference.gd"))return resource.Get("object_type").AsString()=="noise_image"?"Noise Image":"Image";if(resource.ResourceName.Length>0)return resource.ResourceName;}return value.VariantType==Variant.Type.String?value.AsString().GetFile():"<embedded>";}
    public string file_resource_tooltip(Variant value)=>value.VariantType==Variant.Type.String?value.AsString():"Embedded resource";
    public Settings shader_texture_options()=>new(){["extensions"]=ImageExtensions.Concat(new[]{"tres","res"}).ToArray(),["raw_extensions"]=(string[])ImageExtensions.Clone(),["accepted_object_types"]=new GArray{"image","noise_image"},["native_resource_types"]=new GArray{"Texture2D"},["shader_texture"]=true,["file_picker"]=true};
    public Resource? noise_object_from_value(Control owner,Variant value){Resource? data=null;if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd"))data=owner.Call("_resolve_object",reference).As<Resource>();else if(value.VariantType==Variant.Type.String&&value.AsString().GetExtension().ToLowerInvariant() is "tres" or "res")data=ResourceLoader.Load(value.AsString(),"",ResourceLoader.CacheMode.Ignore);return ActorDataOperations.ScriptIs(data,"res://scripts/actors/core/actor_object_data.gd")&&data!.Get("type_id").AsString()=="noise_image"?data:null;}
}
